// Creates apps/cloud-api/.env with fresh dev secrets if it does not exist yet.
import { randomBytes } from "node:crypto";
import { existsSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const file = join(import.meta.dirname, "..", ".env");
if (existsSync(file)) {
  console.log(".env already present");
} else {
  writeFileSync(
    file,
    [
      "# Local development only. Generated by `npm run env:init`; never commit.",
      'DATABASE_URL="postgresql://droplet:droplet-dev@127.0.0.1:5544/droplet"',
      `DROPLET_SIGNING_SECRET="${randomBytes(32).toString("base64url")}"`,
      `DROPLET_MFA_ENC_KEY="${randomBytes(32).toString("hex")}"`,
      'PORTAL_ORIGIN="http://localhost:5173"',
      'PUBLIC_BASE_URL="http://localhost:5173"',
      "RUN_SWEEPER=1",
      "",
    ].join("\n"),
  );
  console.log("wrote .env");
}
